def rects(g):
    bg=g[0][0]; seen=set(); res=[]
    for i,row in enumerate(g):
        for j,v in enumerate(row):
            if v!=bg and (i,j) not in seen:
                # bounding box of color v component
                q=[(i,j)]; seen.add((i,j)); cells=[]
                while q:
                    a,b=q.pop(); cells.append((a,b))
                    for da,db in((1,0),(-1,0),(0,1),(0,-1)):
                        x,y=a+da,b+db
                        if 0<=x<len(g) and 0<=y<len(g[0]) and g[x][y]==v and (x,y) not in seen:
                            seen.add((x,y)); q.append((x,y))
                r0=min(c[0] for c in cells);r1=max(c[0] for c in cells)
                c0=min(c[1] for c in cells);c1=max(c[1] for c in cells)
                res.append((v,r0,r1,c0,c1))
    return res
